import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.B3amng90.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function h(l,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="看不到需要的模型或按钮不可用" tabindex="-1">看不到需要的模型或按钮不可用 <a class="header-anchor" href="#看不到需要的模型或按钮不可用" aria-label="Permalink to &quot;看不到需要的模型或按钮不可用&quot;">​</a></h2><p>模型和功能由当前服务开放。确认已登录，并切换到对应创作方式；如果模型缺失、脚本生成不可用或按钮显示禁用状态，请联系服务支持，不需要自行添加密钥或修改设置。</p><h2 id="额度不足或费用不确定" tabindex="-1">额度不足或费用不确定 <a class="header-anchor" href="#额度不足或费用不确定" aria-label="Permalink to &quot;额度不足或费用不确定&quot;">​</a></h2><p>提交前查看页面显示的费用和平台额度提示。具体计价以提交时页面说明为准；额度不足时，按当前服务提供的充值或支持入口处理。</p><h2 id="生成任务等待很久" tabindex="-1">生成任务等待很久 <a class="header-anchor" href="#生成任务等待很久" aria-label="Permalink to &quot;生成任务等待很久&quot;">​</a></h2><p>视频通常比图片处理时间更长。查看任务当前状态并保持页面联网；任务仍在执行时不要重复提交相同内容。</p><h2 id="任务失败了怎么办" tabindex="-1">任务失败了怎么办 <a class="header-anchor" href="#任务失败了怎么办" aria-label="Permalink to &quot;任务失败了怎么办&quot;">​</a></h2><p>先查看任务提示，再确认素材格式、模型选择和生成参数符合页面要求。可以缩短提示词、减少参考素材或降低生成规格后重试。连续失败时记录发生时间和功能入口，联系服务支持。</p><h2 id="上传素材失败" tabindex="-1">上传素材失败 <a class="header-anchor" href="#上传素材失败" aria-label="Permalink to &quot;上传素材失败&quot;">​</a></h2><p>确认文件类型和大小符合上传区域的提示，检查网络后重试。商品创作需要上传同一商品的图片；如果仍失败，可换一张较小的图片测试。</p><h2 id="画布修改没有显示" tabindex="-1">画布修改没有显示 <a class="header-anchor" href="#画布修改没有显示" aria-label="Permalink to &quot;画布修改没有显示&quot;">​</a></h2><p>画布会自动保存。等待页面完成保存后再离开；如果同时在多个标签页编辑，按冲突提示确认要保留的版本。</p><h2 id="如何反馈问题" tabindex="-1">如何反馈问题 <a class="header-anchor" href="#如何反馈问题" aria-label="Permalink to &quot;如何反馈问题&quot;">​</a></h2><p>提供功能入口、操作步骤、发生时间和错误提示。截图或描述中请遮住账号信息、额度、私人作品、剧本原文和任何密钥。</p>',15)])])}const _=e(i,[["render",h]]);export{u as __pageData,_ as default};
